CREATE OR REPLACE FUNCTION public.fn_autoclear_featured_on_visibility_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF NEW.visibility <> 'public' THEN
    NEW.is_featured_on_landing := false;
    NEW.featured_nominated_by := NULL;
    NEW.featured_nominated_at := NULL;
    NEW.featured_approved_by := NULL;
    NEW.featured_approved_at := NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_badge_check_flashcards()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_total_flashcards INTEGER;
  v_subject_count    INTEGER;
BEGIN
  -- Read counter updated by trg_aaa_counter_flashcards (fired first)
  SELECT total_flashcards
  INTO v_total_flashcards
  FROM user_stats
  WHERE user_id = NEW.user_id;

  -- Memory Architect: 10 flashcards total
  IF v_total_flashcards >= 10 THEN
    PERFORM award_badge(NEW.user_id, 'memory_architect');
  END IF;

  -- Deck Builder: 50 flashcards total
  IF v_total_flashcards >= 50 THEN
    PERFORM award_badge(NEW.user_id, 'deck_builder');
  END IF;

  -- Subject Expert: 20 flashcards in the SAME subject
  -- Only runs COUNT for the specific subject_id of the new card.
  IF NEW.subject_id IS NOT NULL THEN
    SELECT COUNT(*)
    INTO v_subject_count
    FROM flashcards
    WHERE user_id   = NEW.user_id
      AND subject_id = NEW.subject_id;

    IF v_subject_count >= 20 THEN
      PERFORM award_badge(NEW.user_id, 'subject_expert');
    END IF;
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_badge_check_friendships()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user_friends   INTEGER;
  v_friend_friends INTEGER;
BEGIN
  -- Only run when a friendship becomes 'accepted'
  IF TG_OP = 'UPDATE' AND NEW.status = 'accepted' AND OLD.status != 'accepted' THEN

    -- Read updated friend counts (already incremented by counter trigger)
    SELECT total_friends INTO v_user_friends
    FROM user_stats WHERE user_id = NEW.user_id;

    SELECT total_friends INTO v_friend_friends
    FROM user_stats WHERE user_id = NEW.friend_id;

    -- Social Learner: 3 friends
    IF v_user_friends >= 3 THEN
      PERFORM award_badge(NEW.user_id, 'social_learner');
    END IF;
    IF v_friend_friends >= 3 THEN
      PERFORM award_badge(NEW.friend_id, 'social_learner');
    END IF;

    -- Community Pillar: 10 friends
    IF v_user_friends >= 10 THEN
      PERFORM award_badge(NEW.user_id, 'community_pillar');
    END IF;
    IF v_friend_friends >= 10 THEN
      PERFORM award_badge(NEW.friend_id, 'community_pillar');
    END IF;

  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_badge_check_notes()
