$function$

CREATE OR REPLACE FUNCTION public.fn_badge_check_reviews()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_total_reviews INTEGER;
  v_streak        INTEGER;
  v_user_tz       TEXT;
  v_local_hour    INTEGER;
BEGIN
  -- Read counter updated by trg_aaa_counter_reviews (fired first)
  SELECT total_reviews
  INTO v_total_reviews
  FROM user_stats
  WHERE user_id = NEW.user_id;

  -- Log activity for streak and time-based badge calculations
  PERFORM log_review_activity(NEW.user_id, NEW.created_at);

  -- First Steps: very first review
  IF v_total_reviews >= 1 THEN
    PERFORM award_badge(NEW.user_id, 'first_steps');
  END IF;

  -- Century Club: 100 total reviews
  IF v_total_reviews >= 100 THEN
    PERFORM award_badge(NEW.user_id, 'century_club');
  END IF;

  -- Review Veteran: 500 total reviews
  IF v_total_reviews >= 500 THEN
    PERFORM award_badge(NEW.user_id, 'review_veteran');
  END IF;

  -- Streak-based badges (requires function call to user_activity_log)
  v_streak := get_user_streak(NEW.user_id);

  IF v_streak >= 3 THEN
    PERFORM award_badge(NEW.user_id, 'streak_master');
  END IF;

  IF v_streak >= 7 THEN
    PERFORM award_badge(NEW.user_id, 'committed_learner');
  END IF;

  IF v_streak >= 30 THEN
    PERFORM award_badge(NEW.user_id, 'monthly_master');
  END IF;

  -- Time-based badges: convert review timestamp to user's local timezone
  SELECT COALESCE(timezone, 'Asia/Kolkata')
  INTO v_user_tz
  FROM profiles
  WHERE id = NEW.user_id;

  v_local_hour := EXTRACT(HOUR FROM (NEW.created_at AT TIME ZONE v_user_tz))::INTEGER;

  -- Night Owl: 11 PM to 4 AM local time (hours 23, 0, 1, 2, 3, 4)
  IF v_local_hour = 23 OR v_local_hour BETWEEN 0 AND 4 THEN
    PERFORM award_badge(NEW.user_id, 'night_owl');
  END IF;

  -- Early Bird: 5 AM to 6:59 AM local time (hours 5, 6)
  IF v_local_hour BETWEEN 5 AND 6 THEN
    PERFORM award_badge(NEW.user_id, 'early_bird');
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_badge_check_upvotes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_upvotes_given    INTEGER;
  v_upvotes_received INTEGER;
  v_owner_id         UUID;
BEGIN
  IF TG_OP = 'INSERT' THEN

    -- Check helpful_peer for the upvoter
    SELECT total_upvotes_given
    INTO v_upvotes_given
    FROM user_stats
    WHERE user_id = NEW.user_id;

    IF v_upvotes_given >= 10 THEN
      PERFORM award_badge(NEW.user_id, 'helpful_peer');
    END IF;

    -- Find content owner to check rising_star
    IF NEW.content_type = 'note' THEN
      SELECT user_id INTO v_owner_id FROM notes WHERE id = NEW.target_id;
    ELSIF NEW.content_type = 'flashcard_deck' THEN
      SELECT user_id INTO v_owner_id FROM flashcard_decks WHERE id = NEW.target_id;
    END IF;

    -- Only check if it is someone else's content
    IF v_owner_id IS NOT NULL AND v_owner_id != NEW.user_id THEN
      SELECT total_upvotes_received
      INTO v_upvotes_received
      FROM user_stats
      WHERE user_id = v_owner_id;

      -- Rising Star: 5 upvotes received
      IF v_upvotes_received >= 5 THEN
        PERFORM award_badge(v_owner_id, 'rising_star');
      END IF;
    END IF;

  END IF;

  RETURN NULL;
END;
$function$

