CREATE OR REPLACE FUNCTION public.fn_sync_profile_email_from_auth()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_old   text;
  v_new   text := lower(btrim(NEW.email));
  v_actor uuid := auth.uid();   -- the signed-in user whose request caused this change; NULL for dashboard / service role
BEGIN
  SELECT email INTO v_old FROM public.profiles WHERE id = NEW.id;
  IF NOT FOUND THEN
    -- Do not create a partially formed profile here; creation is the signup trigger's job.
    RAISE WARNING 'email sync: no profile row for auth user %, nothing updated', NEW.id;
    RETURN NEW;
  END IF;

  UPDATE public.profiles SET email = v_new WHERE id = NEW.id;   -- unique violation here aborts the Auth update

  INSERT INTO public.admin_audit_log (action, admin_id, target_user_id, details)
  VALUES ('email_changed',
          CASE WHEN v_actor IS NOT NULL AND v_actor <> NEW.id THEN v_actor ELSE NULL END,
          NEW.id,
          jsonb_build_object('old_email', COALESCE(OLD.email, v_old), 'new_email', NEW.email,
                             'mechanism', CASE WHEN v_actor = NEW.id THEN 'self_service' ELSE 'dashboard_or_admin' END,
                             'via', 'fn_sync_profile_email_from_auth'));
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_update_upvotes_counter()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_owner_id UUID;
BEGIN
  IF TG_OP = 'INSERT' THEN

    -- Increment upvotes given for the upvoter
    INSERT INTO user_stats (user_id, total_upvotes_given, updated_at)
    VALUES (NEW.user_id, 1, NOW())
    ON CONFLICT (user_id) DO UPDATE
      SET total_upvotes_given = user_stats.total_upvotes_given + 1,
          updated_at          = NOW();

    -- Locate content owner
    IF NEW.content_type = 'note' THEN
      SELECT user_id INTO v_owner_id FROM notes WHERE id = NEW.target_id;
    ELSIF NEW.content_type = 'flashcard_deck' THEN
      SELECT user_id INTO v_owner_id FROM flashcard_decks WHERE id = NEW.target_id;
    END IF;

    -- Increment upvotes received for the content owner (only if it's someone else's content)
    IF v_owner_id IS NOT NULL AND v_owner_id != NEW.user_id THEN
      INSERT INTO user_stats (user_id, total_upvotes_received, updated_at)
      VALUES (v_owner_id, 1, NOW())
      ON CONFLICT (user_id) DO UPDATE
        SET total_upvotes_received = user_stats.total_upvotes_received + 1,
            updated_at             = NOW();
    END IF;

  ELSIF TG_OP = 'DELETE' THEN

    -- Decrement upvotes given
    UPDATE user_stats
    SET total_upvotes_given = GREATEST(0, total_upvotes_given - 1),
        updated_at          = NOW()
    WHERE user_id = OLD.user_id;

    -- Locate content owner
    IF OLD.content_type = 'note' THEN
      SELECT user_id INTO v_owner_id FROM notes WHERE id = OLD.target_id;
    ELSIF OLD.content_type = 'flashcard_deck' THEN
      SELECT user_id INTO v_owner_id FROM flashcard_decks WHERE id = OLD.target_id;
    END IF;

    -- Decrement upvotes received for the content owner
    IF v_owner_id IS NOT NULL AND v_owner_id != OLD.user_id THEN
      UPDATE user_stats
      SET total_upvotes_received = GREATEST(0, total_upvotes_received - 1),
          updated_at             = NOW()
      WHERE user_id = v_owner_id;
    END IF;

  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_upvote_counts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Increment count based on content type
    IF NEW.content_type = 'note' THEN
      UPDATE notes 
      SET upvote_count = COALESCE(upvote_count, 0) + 1 
      WHERE id = NEW.target_id;
    ELSIF NEW.content_type = 'flashcard_deck' THEN
      UPDATE flashcard_decks 
      SET upvote_count = COALESCE(upvote_count, 0) + 1 
      WHERE id = NEW.target_id;
    END IF;
    RETURN NEW;
    
  ELSIF TG_OP = 'DELETE' THEN
    -- Decrement count based on content type
    IF OLD.content_type = 'note' THEN
      UPDATE notes 
      SET upvote_count = GREATEST(COALESCE(upvote_count, 0) - 1, 0) 
      WHERE id = OLD.target_id;
    ELSIF OLD.content_type = 'flashcard_deck' THEN
      UPDATE flashcard_decks 
      SET upvote_count = GREATEST(COALESCE(upvote_count, 0) - 1, 0) 
      WHERE id = OLD.target_id;
    END IF;
    RETURN OLD;
  END IF;
  
  RETURN NULL;
END;
$function$
